// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 n, uint64 ts, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(uint256(ts) > 0);
        vm.roll(n);
        vm.warp(uint256(ts));

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        if (block.number % 15 == 0) {
            // Rule: after a winning call, C sends its whole balance to the caller.
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance >= 10 ether);
        }
    }
}
